// Eagle Light font, base64-encoded TTF.
// Used at runtime by both the on-screen UI (via @font-face) and the
// generated PDF (via jsPDF addFileToVFS). Eagle Light is a display
// face from Font Bureau — beautiful for headings and large numbers,
// but too tight at small sizes for body text. Per the design-system
// hierarchy, Eagle Light is used ONLY for display roles (the INVOICE
// title, the Balance Due figure, large entity names). Libre Baskerville
// covers body, DM Mono covers tracker labels and codes.
export const EAGLE_LIGHT_B64 = ``;

// Inject Eagle Light into the document via @font-face. Called once
// on mount. Idempotent — won't double-register.
export function installEagleLightWebFont() {
  if (typeof document === "undefined") return;
  if (document.getElementById("eagle-light-face")) return;
  const style = document.createElement("style");
  style.id = "eagle-light-face";
  style.textContent = `
    @font-face {
      font-family: 'Eagle Light';
      font-style: normal;
      font-weight: 300;
      font-display: swap;
      src: url(data:font/ttf;base64,${EAGLE_LIGHT_B64}) format('truetype');
    }
  `;
  document.head.appendChild(style);
}
